#!/bin/bash
set -e

# ==============================================================
# kaviancrypto v7.2 Pro Terminal - Complete All-in-One Installer
# Strategy Studio Pro Upgrade:
#   1) Dynamic Per-Strategy Parameters Menu (Categorized Switches,
#      Dropdowns & Number Inputs -> Lossless Apply to Code / Save)
#   2) Quick Walk-Forward Backtester (500 Bars, Zero Lookahead,
#      TP1 Risk-Free / TP2 Trail, Equity Curve + Clickable Charts)
#   3) Multi-TF Matrix Test (All 5 Timeframes 15M->1W in One Shot)
#   4) Saved Strategy Presets Library + Direct .py Import & Export
#   5) Editor Ergonomics (Expand Full-Width, Find / :Line Jump,
#      Auto-Jump to Syntax Error Line)
# + Unified Obsidian Gold Pro Palette (Obsidian & Bento HUD)
# + Clean Overview Hierarchy + Dedicated Full-Screen Live Console
# Fresh Install + Safe Repair/Upgrade (Preserves config.json,
# active_trades.json, sent_signals.json, strategy_presets.json
# & custom_strategy.py)
# ==============================================================

APP_DIR="/opt/kaviancrypto"
PORT="8888"

echo "========================================================"
echo "  kaviancrypto v7.2 Pro - All-in-One Installer & Upgrade"
echo "  Strategy Parameters Menu + 500-Bar Backtest + Presets"
echo "========================================================"

echo "=== [1/6] Stopping existing service (if running) & preparing $APP_DIR ==="
systemctl stop kaviancrypto.service 2>/dev/null || true
mkdir -p "$APP_DIR"
cd "$APP_DIR"

SCRIPT_SRC="$(readlink -f "$0" 2>/dev/null || echo "$0")"
if [ -f "$SCRIPT_SRC" ] && [ "$SCRIPT_SRC" != "$APP_DIR/install_kaviancrypto_v7_2.sh" ]; then
    cp -f "$SCRIPT_SRC" "$APP_DIR/install_kaviancrypto_v7_2.sh" 2>/dev/null || true
    chmod +x "$APP_DIR/install_kaviancrypto_v7_2.sh" 2>/dev/null || true
fi

echo "=== [2/6] Installing system prerequisites ==="
apt-get update -y
apt-get install -y python3 python3-venv python3-pip curl

echo "=== [3/6] Extracting verified kaviancrypto v7.2 core files ==="
